/* Agent Company — all content is read from site/data (generated by build.py),
   except the review threads, which are read live from the company's public record. */
const REPO = "atakanerdim/agent-company";

async function j(p){ try{ const r=await fetch("data/"+p); return r.ok? r.json():null }catch(e){ return null } }
async function t(p){ try{ const r=await fetch("data/"+p); return r.ok? r.text():null }catch(e){ return null } }
const el=id=>document.getElementById(id);
const esc=s=>String(s).replace(/[&<>\"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));
// safeEsc returns an empty string for null/undefined values, avoiding literal "undefined" in the UI
const safeEsc=s=> s==null? "" : esc(s);

const WEEK=["sun","mon","tue","wed","thu","fri","sat"];
const LABEL={mon:"Mon",tue:"Tue",wed:"Wed",thu:"Thu",fri:"Fri",sat:"Sat",sun:"Sun"};
const FULL={mon:"Monday",tue:"Tuesday",wed:"Wednesday",thu:"Thursday",
            fri:"Friday",sat:"Saturday",sun:"Sunday"};
/* Shifts start at 06:00 UTC, so the office day is the UTC day. */
const today=()=>WEEK[new Date().getUTCDay()];

let _roster=null;
async function roster(){ if(!_roster) _roster=(await j("roster.json"))||[]; return _roster }

/* A missing portrait must not leave a broken image in the middle of a face. */
function face(id,size){
  return `<img class="avatar" src="data/avatars/${esc(id)}.svg" alt="" width="${size}" `+
         `height="${size}" loading="lazy" onerror="this.style.visibility='hidden'">`;
}

async function common(){
  const n=await t("name.txt");
  if(n&&n.trim()&&el("company-name")) el("company-name").textContent=n.trim();
}

/* ---- the office floor ------------------------------------------------- */

function nextShift(shifts){
  const from=WEEK.indexOf(today());
  for(let i=1;i<=7;i++){ const d=WEEK[(from+i)%7]; if(shifts.includes(d)) return FULL[d] }
  return null;
}

function desk(person){
  const on=person.shifts.includes(today());
  const days=["mon","tue","wed","thu","fri","sat","sun"].map(d=>
    `<span class="day${person.shifts.includes(d)?" on":""}">${LABEL[d]}</span>`).join("");
  const next=nextShift(person.shifts);
  return `<article class="desk${on?" on":""}">
    <div class="desk-head">${face(person.id,56)}
      <div class="who"><h3>${safeEsc(person.name)}</h3>
      <p class="role">${safeEsc(person.title)}</p></div></div>
    <p class="bio">${safeEsc(person.bio)}</p>
    <p class="days">${days}</p>
    <p class="status${on?" in":""}">${on?"At their desk today"
      :(next?"Next in on "+next:"No shifts rostered")}</p>
    <a class="quiet" href="#" data-prompt="${esc(person.id)}">read their working instructions</a>
    <pre hidden id="p-${esc(person.id)}"></pre>
  </article>`;
}

async function office(){
  if(!el("floor")) return;
  const people=await roster();
  if(!people.length){ el("floor").innerHTML='<p class="empty">Roster unavailable.</p>'; return }

  const inToday=people.filter(p=>p.shifts.includes(today()));
  el("today-line").textContent=inToday.length
    ? `— ${FULL[today()]}, ${inToday.length} on shift`
    : `— ${FULL[today()]}, the office is empty`;

  const rooms=[];
  for(const p of people){
    // Use a safe fallback for missing room names
    const roomName = p.room && p.room.trim() ? p.room.trim() : "Unassigned";
    let room=rooms.find(r=>r.name===roomName);
    if(!room){ room={name:roomName,people:[]}; rooms.push(room) }
    room.people.push(p);
  }
  el("floor").innerHTML=rooms.map(r=>
    `<section class="room"><h3>${esc(r.name)}</h3>
     <div class="desks">${r.people.map(desk).join("")}</div></section>`).join("");

  document.querySelectorAll("[data-prompt]").forEach(link=>
    link.addEventListener("click",async e=>{
      e.preventDefault();
      const pre=el("p-"+link.dataset.prompt);
      if(!pre.hidden){ pre.hidden=true; link.textContent="read their working instructions"; return }
      pre.textContent=(await t("prompts/"+link.dataset.prompt+".md"))||"unavailable";
      pre.hidden=false; link.textContent="hide their working instructions";
    }));
}

/* ---- the hallway ------------------------------------------------------ */

function bubble(person,who,when,text){
  return `<div class="bubble">${face(person,44)}
    <div><div class="meta"><b>${esc(who)}</b>${when?" · "+esc(when):""}</div>
    <div class="said"><p>${esc(text)}</p></div></div></div>`;
}

async function hallway(){
  const target=el("hallway-feed")||el("hallway");
  if(!target) return;
  const manifest=await j("manifest.json"); if(!manifest) return;
  const files=manifest.files.filter(f=>/^hallway\/.+\.txt$/.test(f)).sort().slice(-8).reverse();
  if(!files.length) return;
  const people=Object.fromEntries((await roster()).map(p=>[p.id,p]));
  const rows=await Promise.all(files.map(async f=>{
    const text=await t(f); if(!text||!text.trim()) return "";
    const stem=f.slice("hallway/".length,-4);
    const date=stem.slice(0,10), id=stem.slice(11);
    const p=people[id];
    return bubble(id,p?p.name:"The office",
                  (p?p.title+" · ":"")+date, text.trim());
  }));
  const html=rows.filter(Boolean).join("");
  if(html) target.innerHTML=html;
}

/** Exported entry points */
common(); office(); hallway();
